#include "stdlib/math/base/special/ceilnf.h"
#include "stdlib/math/base/special/ceilf.h"
#include "stdlib/math/base/special/absf.h"
#include "stdlib/math/base/special/pow.h"
#include "stdlib/math/base/assert/is_nanf.h"
#include "stdlib/math/base/assert/is_infinitef.h"
#include "stdlib/constants/float32/max_base10_exponent.h"
#include "stdlib/constants/float32/min_base10_exponent.h"
#include "stdlib/constants/float32/min_base10_exponent_subnormal.h"
#include "stdlib/constants/float32/max_safe_integer.h"
#include "stdlib/constants/float32/pinf.h"
#include <stdint.h>
#include <math.h>


// VARIABLES //

static const float MAX_INT = STDLIB_CONSTANT_FLOAT32_MAX_SAFE_INTEGER + 1.0f;
static const float HUGE_VALUE = 1.0e+38f;


// MAIN //

/**
* Rounds a single-precision floating-point numeric value to the nearest multiple of 10^n toward positive infinity.
*
* @param x       input value
* @param n       integer power of 10
* @return        rounded value
*
* @example
* // Round a value to 2 decimal places:
* float y = stdlib_base_ceilnf( 3.141592653589793f, -2f );
* // returns 3.15f
*
* @example
* // If n = 0, `ceilnf` behaves like `ceilf`:
* float y = stdlib_base_ceilnf( 3.141592653589793f, 0f );
* // returns 4.0f
*
* @example
* // Round a value to the nearest thousand:
* float y = stdlib_base_ceilnf( 12368.0f, 3f );
* // returns 13000.0f
*/
float stdlib_base_ceilnf( const float x, const int32_t n ) {
	float s;
	float y;
	if ( stdlib_base_is_nanf( x ) ) {
		return x;
	}
	if (
		// Handle infinities...
		stdlib_base_is_infinitef( x ) ||

		// Handle +-0...
		x == 0.0f ||

		// If `n` exceeds the maximum number of feasible decimal places (such as with subnormal numbers), nothing to round...
		n < STDLIB_CONSTANT_FLOAT32_MIN_BASE10_EXPONENT_SUBNORMAL ||

		// If `|x|` is large enough, no decimals to round...
		( stdlib_base_absf( x ) > MAX_INT && n <= 0 )
	) {
		return x;
	}
	// The maximum absolute float is ~1.8e38. Accordingly, any possible positive finite `x` rounded to the nearest >=10^39 is infinity and any negative finite `x` is zero.
	if ( n > STDLIB_CONSTANT_FLOAT32_MAX_BASE10_EXPONENT ) {
		if ( x <= 0.0f ) {
			return -0.0f; // preserve the sign (same behavior as ceilf)
		}
		return STDLIB_CONSTANT_FLOAT32_PINF;
	}
	// If we overflow, return `x`, as the number of digits to the right of the decimal is too small (i.e., `x` is too large / lacks sufficient fractional precision) for there to be any effect when rounding...
	if ( n < STDLIB_CONSTANT_FLOAT32_MIN_BASE10_EXPONENT ) {
		s = stdlib_base_pow( 10.0f, -( n + STDLIB_CONSTANT_FLOAT32_MAX_BASE10_EXPONENT ) ); // TODO: replace use of `pow` once have stdlib equivalent
		y = ( x * HUGE_VALUE ) * s; // order of operation matters!
		if ( stdlib_base_is_infinitef( y ) ) {
			return x;
		}
		return ( stdlib_base_ceilf( y ) / HUGE_VALUE ) / s;
	}
	s = stdlib_base_pow( 10.0f, -n ); // TODO: replace use of `pow` once have stdlib equivalent
	y = x * s;
	if ( stdlib_base_is_infinitef( y ) ) {
		return x;
	}
	return stdlib_base_ceilf( y ) / s;
}
